let currentCountry = ""; // Variable para recordar el último país válido

const cleanedData = rawData
  .map(obj => {
    // 1. Si el objeto tiene un país válido, actualizamos el nombre actual
    if (obj.country && obj.country !== "---" && obj.country !== "" && obj.country !== "País" && obj.country !== "country") {
      currentCountry = obj.country;
    }

    // 2. Retornamos una copia con el país "arrastrado"
    return { ...obj, country: currentCountry };
  })
  .filter(obj => {
    // 3. Ahora filtramos: eliminamos filas que sigan siendo basura o no tengan año
    const isInvalidYear = !obj.year || obj.year === "---" || obj.year === "Año";
    const isInvalidCountry = !obj.country || obj.country === "---";
    
    return !isInvalidYear && !isInvalidCountry;
  })
  .map(obj => {
    // 4. Limpieza final de atributos
    const newObj = { ...obj };

    delete newObj.best_year;

    // Normalizar variación para 2018 o casos de "---"
    if (newObj.year === 2018 || newObj.rank_variation_from_two_thousand_eighteen === "---") {
      newObj.rank_variation_from_two_thousand_eighteen = 0;
    }

    return newObj;
  });

const fileContent = `export const countriesData = ${JSON.stringify(cleanedData, null, 2)};`;
/*
console.log(rawData.length);
console.log(cleanedData.length);*/
export default cleanedData;